test('ordered migrations upgrade a pre-ledger foundation database, rerun safely and reject modified migration checksums', async () => {
  const schema = `upgrade_test_${randomUUID().replaceAll('-', '')}`;
  const client = await context.adminPool!.connect();
  try {
    await client.query('BEGIN');
    await client.query(`CREATE SCHEMA "${schema}"`);
    await client.query(`SET LOCAL search_path TO "${schema}", public`);
    await client.query(await readFile(new URL('../migrations/001_foundation.sql', import.meta.url), 'utf8'));
    await client.query('COMMIT');
    await runMigrations(context.adminPool!, schema);
    await runMigrations(context.adminPool!, schema);
    const result = await client.query(`SELECT filename,sha256 FROM "${schema}".schema_migrations ORDER BY filename`);
    assert.deepEqual(result.rows.map(r => r.filename), ['001_foundation.sql', '002_casework.sql', '003_binary_originals.sql', '004_integrity_jobs.sql', '005_text_derivatives.sql', '006_claim_source_identity.sql', '007_report_revisions.sql', '008_report_revision_listing.sql', '009_job_history_indexes.sql', '010_dispatch_candidates.sql', '011_upload_reservations.sql', '012_upload_maintenance.sql', '013_upload_history.sql', '014_report_review.sql', '015_report_disclosures.sql', '016_disclosure_recipient_index.sql', '017_disclosure_acknowledgements.sql', '018_disclosure_case_history.sql', '019_session_owner_index.sql', '020_session_epoch.sql', '021_job_lease_deadline.sql', '022_document_derivatives.sql', '023_raster_derivatives.sql', '024_document_citation_candidates.sql', '025_document_citation_reviews.sql', '026_document_derived_findings.sql', '027_document_disclosure_packages.sql', '028_report_renditions.sql', '029_reviewed_pdf_disclosures.sql', '030_ocr_document_derivatives.sql', '031_document_work_links.sql', '032_chronology.sql', '033_provider_identity.sql', '034_saved_case_views.sql', '035_work_discussions.sql', '036_case_graph.sql', '037_manual_sources.sql', '038_assigned_work_queue_index.sql', '039_case_lifecycle.sql', '040_interview_transcripts.sql', '041_case_access.sql', '042_case_time_ledger.sql', '043_preservation_holds.sql', '044_attention_queue.sql', '045_expanded_document_profiles.sql', '046_case_time_budgets.sql', '047_task_status_batches.sql', '048_field_capture.sql', '049_transcript_findings.sql', '050_transcript_work_links.sql', '051_transcript_graph_sources.sql', '052_case_invitations.sql', '053_source_use_decisions.sql', '054_case_expenses.sql', '055_editable_report_renditions.sql', '056_task_plan_batches.sql', '057_reviewed_docx_disclosures.sql', '058_review_assignments.sql', '059_speech_derivatives.sql', '060_speech_findings.sql', '061_connector_policies.sql', '062_collection_jobs.sql']);
    assert.equal((await client.query(`SELECT count(*)::int AS count FROM "${schema}".users`)).rows[0].count, 1);
    await client.query(`UPDATE "${schema}".schema_migrations SET sha256=$1 WHERE filename='002_casework.sql'`, ['0'.repeat(64)]);
    await assert.rejects(runMigrations(context.adminPool!, schema), /Applied migration was modified/);
  } finally {
    await client.query('ROLLBACK');
    await client.query(`DROP SCHEMA IF EXISTS "${schema}" CASCADE`);
    client.release();
  }
});

