test('case lifecycle preserves attributed stages, replay, conflicts, restart and fresh authority on reopening',async()=>{
 const f=await lifecycleFixture();assert.equal((await f.read()).state,'Intake');assert.equal((await f.read()).collectionOpen,false);
 assertError(await f.move('Active'),409);assert.equal((await f.move('Scope review')).statusCode,200);assert.equal((await approveAuthority(f.kase.id)).statusCode,200);
 const active=await f.read();assert.equal(active.state,'Active');assert.equal(active.version,3);assert.equal(active.collectionOpen,true);assert.equal(active.history[0].authorityVersion,1);
 const input={id:randomUUID(),expectedVersion:active.version,to:'Review',reason:'Fictional review phase started with all outstanding checks retained.'};const first=await request('POST',f.base,context.demo!,{payload:input});assert.equal(first.statusCode,200,first.body);assert.equal((await request('POST',f.base,context.demo!,{payload:input})).json().version,4);
 assertError(await request('POST',f.base,context.demo!,{payload:{...input,reason:'Fictional changed retry must not replace history.'}}),409);
 const race=await Promise.all(['Active','Closed'].map(to=>request('POST',f.base,context.demo!,{payload:{id:randomUUID(),expectedVersion:4,to,reason:'Fictional concurrent decision must preserve one result.'}})));assert.deepEqual(race.map(r=>r.statusCode).sort(),[200,409]);
 if((await f.read()).state!=='Closed')assert.equal((await f.move('Closed')).statusCode,200);
 assertError(await approveAuthority(f.kase.id),409);assert.equal((await f.move('Archived')).statusCode,200);assert.equal((await f.move('Scope review')).statusCode,200);assert.equal((await f.read()).collectionOpen,false);assertError(await uploadEvidence(f.kase.id),409);
 assert.equal((await approveAuthority(f.kase.id)).statusCode,200);const latest=await f.read();assert.equal(latest.history[0].authorityVersion,2);
 await context.app!.close();context.app=await createAppInstance();assert.equal((await f.read()).version,latest.version);
 await assert.rejects(context.pool!.query("UPDATE case_lifecycle_events SET reason='Changed fictional history' WHERE case_id=$1",[f.kase.id]),/permission denied/);
 await assert.rejects(context.schemaAdminPool!.query('DELETE FROM case_lifecycle_events WHERE case_id=$1',[f.kase.id]),/append-only/);
 await assert.rejects(context.pool!.query("UPDATE cases SET lifecycle_state='Closed' WHERE id=$1",[f.kase.id]),/advance exactly one/);
 const replay=await request('POST',f.base,context.demo!,{payload:input});assert.equal(replay.json().version,latest.version);assert.equal(replay.json().state,'Active');
});
