 await context.app!.close();context.app=await createAppInstance();context.demo=await issueTestSession(demoUserId);const kase=await createCase();assert.equal((await approveAuthority(kase.id,context.demo!,{retentionDays:1})).statusCode,200);const evidence=parseBody<Evidence>(await uploadEvidence(kase.id)),base=`/api/cases/${kase.id}/preservation-holds`,input={id:randomUUID(),evidenceId:evidence.id,label:'Fictional preservation instruction',authorityReference:'Fictional reviewer instruction SYN-HOLD-001',purpose:'Preserve supplied fictional material pending a recorded scope review.',reason:'Fictional preservation decision; this does not determine legal validity.'};return {kase,evidence,base,input,create:(payload:Omit<typeof input,'evidenceId'>&{evidenceId:string|null}=input,session=context.demo!)=>request('POST',base,session,{payload}),queue:()=>request('GET',`/api/cases/${kase.id}/retention-review`,context.demo!)};
