  await click('Amend hold');await fill({label:'Fictional amended browser instruction',reason:'Fictional clarification preserves the original scope and earlier wording.'});await click('Save preservation decision');await eventually(async()=>(await ui.text()).includes('Version 2'),'amendment saved');
  const previous=await b.evaluate<number>('performance.timeOrigin');await b.send('Page.reload');await eventually(async()=>await b.evaluate<number>('performance.timeOrigin')!==previous&&(await ui.text()).includes('Fictional amended browser instruction'),'saved preservation reload');await b.evaluate(`document.querySelector('[aria-label="Preservation list"] button').click()`);await eventually(async()=>(await ui.text()).includes('Version 2'),'saved hold selected');await click('Preservation history');await eventually(async()=>(await ui.text()).includes('Retained preservation decisions'),'preservation history visible');await b.evaluate(`document.querySelector('[aria-label="Preservation history"] details:last-of-type summary').click()`);assert.ok((await ui.text()).includes('Fictional browser preservation instruction'));
  const artifact=fileURLToPath(new URL('../../../output/evals/preservation-desktop.png',import.meta.url));await mkdir(resolve(artifact,'..'),{recursive:true});await b.evaluate(`document.querySelector('[aria-label="Selected preservation hold"]').scrollIntoView({block:'start'})`);const shot=await b.send<{data:string}>('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});await writeFile(artifact,Buffer.from(shot.data,'base64'));
  await b.send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});assert.ok(await b.evaluate<boolean>('document.documentElement.scrollWidth<=window.innerWidth+1'));await click('Inspect held original');await eventually(async()=>await b.evaluate<boolean>(`document.querySelector('.evidence-inspector .panel-heading .mono')?.textContent===${JSON.stringify(f.evidence.id)}`),'correct held original selected');await click('Release hold');await fill({reason:'Fictional reviewer explicitly releases this instruction; no destruction is authorised.'});await click('Record hold release');await eventually(async()=>(await ui.text()).includes('Released hold')&&(await ui.text()).includes('Version 3')&&(await ui.text()).includes('No active hold recorded'),'released status and retention queue agree');assert.equal(await b.evaluate(`!![...document.querySelectorAll('[aria-label="Selected preservation hold"] button')].find(x=>x.textContent==='Amend hold')`),false);
  await click('Declare case hold');await fill({label:'Fictional unsaved preservation material'});await context.schemaAdminPool!.query('DELETE FROM case_memberships WHERE tenant_id=$1 AND case_id=$2 AND user_id=$3',[demoTenantId,f.kase.id,demoUserId]);await click('Refresh preservation');await eventually(async()=>await b.evaluate<boolean>(`![...document.querySelectorAll('[aria-label="Active case"] option')].some(o=>o.value===${JSON.stringify(f.kase.id)})&&!document.querySelector('[aria-label="Selected preservation hold"]')&&!document.querySelector('form[aria-label="Preservation decision"]')`)&&!(await ui.text()).includes('Fictional amended browser instruction'),'revoked preservation and unsaved editor cleared');
