  assert.equal((await get(f.base+'/'+f.input.id,investigator)).status,404);assert.equal((await get(f.base+'/'+f.input.id+'/history',investigator)).status,404);const ownPage=await(await get(f.base+'?scope=case',investigator)).json() as {items:{id:string}[];scope:string};assert.deepEqual(ownPage.items.map(x=>x.id),[own.id]);assert.equal(ownPage.scope,'mine');assert.equal((await get(f.base+'/'+own.id+'/history',reviewer)).status,200);assert.equal((await(await get(f.base,reviewer)).json() as {items:unknown[]}).items.length,2);
