test('time ledger audit failures roll back records, corrections and withdrawals',async()=>{
 const f=await timeFixture();await context.schemaAdminPool!.query("CREATE FUNCTION deny_time_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action LIKE 'time.%' THEN RAISE EXCEPTION 'fictional time audit failure'; END IF; RETURN NEW; END $$");const enable=()=>context.schemaAdminPool!.query('CREATE TRIGGER deny_time_audit BEFORE INSERT ON audit_events FOR EACH ROW EXECUTE FUNCTION deny_time_audit()'),disable=()=>context.schemaAdminPool!.query('DROP TRIGGER deny_time_audit ON audit_events');await enable();try{assertError(await f.create(),500);assert.equal((await context.pool!.query('SELECT count(*)::int n FROM case_time_entries WHERE id=$1',[f.input.id])).rows[0].n,0);}finally{await disable();}assert.equal((await f.create()).statusCode,200);
 const correction={...f.input,id:randomUUID(),expectedVersion:1,minutes:50,reason:'Fictional correction must roll back with a failed audit.'};await enable();try{assertError(await request('POST',f.base+'/'+f.input.id+'/corrections',context.demo!,{payload:correction}),500);assertError(await request('POST',f.base+'/'+f.input.id+'/withdraw',context.demo!,{payload:{id:randomUUID(),expectedVersion:1,reason:correction.reason}}),500);assert.equal((await request('GET',f.base+'/'+f.input.id,context.demo!)).json().version,1);assert.equal((await request('GET',f.base+'/'+f.input.id+'/history',context.demo!)).json().items.length,1);}finally{await disable();}assert.equal((await request('POST',f.base+'/'+f.input.id+'/corrections',context.demo!,{payload:correction})).statusCode,200);
});

test('time ledger pages retain all identities and reserve the final version for withdrawal',async()=>{
 const f=await timeFixture(),ids=[f.input.id];assert.equal((await f.create()).statusCode,200);for(let index=0;index<50;index++){const input={...f.input,id:randomUUID(),billable:index%2===0,minutes:1+index};ids.push(input.id);assert.equal((await f.create(input)).statusCode,200);}
 const first=(await request('GET',f.base,context.demo!)).json(),last=(await request('GET',f.base+'?after='+first.next,context.demo!)).json();assert.equal(first.items.length,50);assert.equal(last.items.length,1);assert.equal(last.next,null);assert.deepEqual([...first.items,...last.items].map((r:{id:string})=>r.id),ids.sort());assert.equal((await request('GET',f.base+'?billable=yes',context.demo!)).json().items.length,25);
 await context.app!.close();context.app=await createAppInstance();const path=f.base+'/'+f.input.id;for(let version=1;version<99;version++){const response=await request('POST',path+'/corrections',context.demo!,{payload:{...f.input,id:randomUUID(),expectedVersion:version,reason:`Fictional duration clarification ${version} retains earlier time notes.`}});assert.equal(response.statusCode,200,response.body);}assertError(await request('POST',path+'/corrections',context.demo!,{payload:{...f.input,id:randomUUID(),expectedVersion:99,reason:'Fictional correction beyond the recorded limit.'}}),409);const withdrawn=await request('POST',path+'/withdraw',context.demo!,{payload:{id:randomUUID(),expectedVersion:99,reason:'Fictional final version remains available for an explicit withdrawal.'}});assert.equal(withdrawn.statusCode,200,withdrawn.body);assert.equal(withdrawn.json().version,100);
 const versions:number[]=[];let before:number|null=null;do{const response=await request('GET',path+'/history'+(before?'?before='+before:''),context.demo!);assert.equal(response.statusCode,200,response.body);const page=response.json();assert.ok(page.items.length<=25);versions.push(...page.items.map((r:{version:number})=>r.version));before=page.next;}while(before);assert.deepEqual(versions,Array.from({length:100},(_,i)=>100-i));
});

