  const previous=await b.evaluate<number>('performance.timeOrigin');await b.send('Page.reload');await eventually(async()=>await b.evaluate<number>('performance.timeOrigin')!==previous&&(await ui.text()).includes('Fictional corrected browser work duration.'),'saved time reload');await b.evaluate(`document.querySelector('[aria-label="Time entries"] button').click()`);await eventually(async()=>(await ui.text()).includes('Time version 2'),'saved time selected');await click('Time entry history');await eventually(async()=>(await ui.text()).includes('Retained time decisions'),'history visible');await b.evaluate(`document.querySelector('[aria-label="Time entry history"] details:last-of-type summary').click()`);assert.ok((await ui.text()).includes('Fictional browser time spent comparing supplied records.'));
  const artifact=fileURLToPath(new URL('../../../output/evals/case-time-desktop.png',import.meta.url));await mkdir(resolve(artifact,'..'),{recursive:true});await b.evaluate(`document.querySelector('[aria-label="Selected time entry"]').scrollIntoView({block:'start'})`);const shot=await b.send<{data:string}>('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});await writeFile(artifact,Buffer.from(shot.data,'base64'));
  await b.send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});assert.ok(await b.evaluate<boolean>('document.documentElement.scrollWidth<=window.innerWidth+1'));await click('Withdraw time entry');await fill({reason:'Fictional duplicate work note withdrawn while retaining every prior record.'});await click('Record time withdrawal');await eventually(async()=>(await ui.text()).includes('Withdrawn entry')&&(await ui.text()).includes('Time version 3')&&(await ui.text()).includes('Active time on this page: 0 minutes.'),'withdrawal and page total agree');assert.equal(await b.evaluate(`!![...document.querySelectorAll('[aria-label="Selected time entry"] button')].find(x=>x.textContent==='Correct time entry')`),false);
