test('real browser saves attention preferences, acknowledges without completing work, retries and clears revoked reminders',{skip:process.env.INVEOS_TEST_BROWSER!=='1',timeout:90000},async()=>{
 const f=await attentionFixture();await approveAuthority(f.kase.id);const second=(await createWork(f.kase.id,workInput({kind:'question',title:'Fictional unresolved ownership question',ownerId:f.userId,dueDate:'2020-02-01'}))).json() as WorkItem;context.demo=f.session;let drop=false,dropped=0;
 await withBrowserApp(async(b,origin)=>{const ui=await binaryBrowserControls(b,origin,f.kase.id),open=async()=>{await b.evaluate(`document.querySelector('[aria-label="View notifications"]').click()`);await eventually(async()=>await b.evaluate<boolean>(`!!document.querySelector('[aria-label="Personal attention queue"]')&&!![...document.querySelectorAll('button')].find(b=>b.textContent==='Refresh attention'&&!b.matches(':disabled'))`),'attention loaded');},queue=()=>b.evaluate<string>(`document.querySelector('[aria-label="Personal attention queue"]')?.innerText||''`),toggle=async(label:string)=>{await b.evaluate(`(()=>{const label=[...document.querySelectorAll('[aria-label="Personal attention queue"] label')].find(l=>l.textContent===${JSON.stringify(label)});const input=label?.querySelector('input');if(!input||input.matches(':disabled'))throw new Error('Reminder input unavailable');input.click();})()`);};
  await open();await eventually(async()=>(await queue()).includes(f.work.title)&&(await queue()).includes(second.title),'two live reminders');const artifact=fileURLToPath(new URL('../../../output/evals/attention-desktop.png',import.meta.url));await mkdir(resolve(artifact,'..'),{recursive:true});const shot=await b.send<{data:string}>('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});await writeFile(artifact,Buffer.from(shot.data,'base64'));
  await toggle('Deadlines');await ui.click('Save reminder preferences');await eventually(async()=>(await queue()).includes('No current reminders match'),'saved muted deadlines');const previous=await b.evaluate<number>('performance.timeOrigin');await b.send('Page.reload');await eventually(async()=>await b.evaluate<number>('performance.timeOrigin')!==previous&&(await ui.text()).includes('Register a binary original'),'reloaded reminder account');await open();await eventually(async()=>(await queue()).includes('No current reminders match'),'muting survives reload');assert.equal(await b.evaluate<boolean>(`[...document.querySelectorAll('.attention-preferences label')].find(l=>l.textContent==='Deadlines').querySelector('input').checked`),false);
  await toggle('Deadlines');await ui.click('Save reminder preferences');await eventually(async()=>(await queue()).includes(f.work.title),'reminders enabled');await ui.click('Acknowledge: '+f.work.title);await eventually(async()=>!(await queue()).includes(f.work.title)&&(await queue()).includes(second.title),'personal acknowledgement clears one version');assert.equal((await context.pool!.query('SELECT status FROM case_work_items WHERE id=$1',[f.work.id])).rows[0].status,'To do');
  drop=true;await ui.click('Refresh attention');await eventually(async()=>(await queue()).includes('Previously loaded reminders have been cleared.')&&!(await queue()).includes(second.title),'network failure clears stale reminders');assert.ok(dropped>0,'The proxy actually interrupted the queue response.');drop=false;await ui.click('Retry attention');await eventually(async()=>(await queue()).includes(second.title),'attention recovered');
  await b.send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});assert.ok(await b.evaluate<boolean>('document.documentElement.scrollWidth<=window.innerWidth+1'));await ui.click('Open context: '+second.title);await eventually(async()=>await b.evaluate<boolean>(`!document.querySelector('dialog')&&!!document.getElementById(${JSON.stringify('work-'+second.id)})`),'question opened in its case');await open();await eventually(async()=>(await queue()).includes(second.title),'remaining reminder');await context.schemaAdminPool!.query('DELETE FROM case_memberships WHERE tenant_id=$1 AND case_id=$2 AND user_id=$3',[demoTenantId,f.kase.id,f.userId]);await ui.click('Refresh attention');await eventually(async()=>(await queue()).includes('No current reminders match')&&!(await queue()).includes(second.title),'revoked reminder cleared');
 },{response:(path,status)=>{if(drop&&path==='/api/attention'&&status===200){dropped++;return 'drop';}}});
});

