  const {ocrFixture}=await import('./support/ocr-fixture.js'),sample=ocrFixture(),{ocrExpandedKind,ocrExpandedProfileDigest,ocrProfileDigest}=await import('../src/ocr-derivative.js'),{rasterExpandedKind,rasterExpandedProfileDigest,rasterProfileDigest}=await import('../src/raster-derivative.js');
