test('task status batch validates raw types, bounds and full 50-task transactions',async()=>{
 const f=await taskBatchFixture(51);assertError(await f.save(),422);
 for(const input of [{...f.input,items:[]},{...f.input,items:[{...f.input.items[0],expectedVersion:'1'}]},{...f.input,items:[{...f.input.items[0],expectedVersion:true}]},{...f.input,items:[{...f.input.items[0],expectedVersion:null}]},{...f.input,items:[{...f.input.items[0],id:[f.items[0]!.id]}]},{...f.input,items:f.input.items.slice(0,1),reason:'          '},{...f.input,items:f.input.items.slice(0,1),reason:'Fictional invalid \u0001 control.'},{...f.input,items:f.input.items.slice(0,1),reason:'Fictional invalid \ud800 unicode.'},{...f.input,items:f.input.items.slice(0,1),status:'Resolved'},{...f.input,items:f.input.items.slice(0,1),extra:true}])assertError(await f.save(input),422);
 const response=await f.save({...f.input,items:f.input.items.slice(0,50)});assert.equal(response.statusCode,200,response.body);assert.equal(response.json().applied.length,50);assert.equal((await f.rows()).filter(i=>i.version===2).length,50);assert.equal((await f.rows()).filter(i=>i.version===1).length,1);
 const audits=await context.pool!.query("SELECT action,count(*)::int n FROM audit_events WHERE case_id=$1 AND action IN('work.revised','work.task_batch') GROUP BY action",[f.kase.id]);assert.equal(audits.rows.find(i=>i.action==='work.revised').n,50);assert.equal(audits.rows.find(i=>i.action==='work.task_batch').n,1);
});

