test('task status batch rechecks membership and role after waiting for the case lock',async()=>{
 for(const change of ['membership','role']){const f=await taskBatchFixture(),userId=await createMember(demoTenantId,'investigator','Fictional waiting batch actor');await context.schemaAdminPool!.query('INSERT INTO case_memberships(tenant_id,case_id,user_id) VALUES($1,$2,$3)',[demoTenantId,f.kase.id,userId]);const session=await issueTestSession(userId),lock=await context.schemaAdminPool!.connect();let pending:ReturnType<typeof request>|undefined;
  try{await lock.query('BEGIN');await lock.query('SELECT 1 FROM cases WHERE id=$1 FOR UPDATE',[f.kase.id]);pending=f.save(f.input,session);await eventually(async()=>(await context.adminPool!.query("SELECT 1 FROM pg_stat_activity WHERE usename='inveos_app' AND wait_event_type='Lock' AND query LIKE '%FOR UPDATE OF c%' ")).rowCount!>0,'batch waits for case lock',1000);
   if(change==='membership')await lock.query('DELETE FROM case_memberships WHERE tenant_id=$1 AND case_id=$2 AND user_id=$3',[demoTenantId,f.kase.id,userId]);else await lock.query("UPDATE memberships SET role='client' WHERE tenant_id=$1 AND user_id=$2",[demoTenantId,userId]);await lock.query('COMMIT');assertError(await pending,404);assert.ok((await f.rows()).every(i=>i.version===1));
  }finally{await lock.query('ROLLBACK');lock.release();if(pending)await pending;}
 }
});

