test('real browser batches task statuses, recovers interrupted delivery, rejects stale versions and clears revoked selections',{skip:process.env.INVEOS_TEST_BROWSER!=='1',timeout:90000},async()=>{
 const f=await taskBatchFixture();let dropBatch=true,batchDrops=0,dropWorkspace=false,workspaceDrops=0;
 await withBrowserApp(async(b,origin)=>{
  const ui=await binaryBrowserControls(b,origin,f.kase.id);await ui.click('Tasks');await eventually(async()=>await b.evaluate<boolean>(`!!document.querySelector('[aria-label="Select task: ${f.items[0]!.title}"]')`),'task board loaded');
  const select=async(item:WorkItem)=>b.evaluate(`document.querySelector(${JSON.stringify('[aria-label="Select task: '+item.title+'"]')}).click()`);
  const fill=async(status:string,reason:string)=>b.evaluate(`(()=>{const form=document.querySelector('[aria-label="Task status batch"]');const status=form.elements.namedItem('status');status.value=${JSON.stringify(status)};status.dispatchEvent(new Event('change',{bubbles:true}));const reason=form.elements.namedItem('reason');Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set.call(reason,${JSON.stringify(reason)});reason.dispatchEvent(new Event('input',{bubbles:true}));})()`);
  for(const item of f.items)await select(item);await fill('In progress','Fictional browser starts the three supplied-record tasks.');await ui.click('Save selected task statuses');await eventually(async()=>await b.evaluate<boolean>(`!!document.querySelector('[role="alert"]')&&!![...document.querySelectorAll('button')].find(x=>x.textContent==='Retry unchanged task batch'&&!x.disabled)`),'lost batch response has explicit retry');assert.ok(batchDrops>0);assert.ok((await f.rows()).every(i=>i.version===2));dropBatch=false;await ui.click('Retry unchanged task batch');await eventually(async()=>(await ui.text()).includes('Recorded status changes for 3 tasks.'),'same request recovered');assert.equal((await context.pool!.query('SELECT count(*)::int n FROM task_status_batches WHERE case_id=$1',[f.kase.id])).rows[0].n,1);
  const previous=await b.evaluate<number>('performance.timeOrigin');await b.send('Page.reload');await eventually(async()=>await b.evaluate<number>('performance.timeOrigin')!==previous&&await b.evaluate<boolean>(`!!document.querySelector('#work-${f.items[0]!.id}')`),'saved task board restored');
  await select(f.items[1]!);await select(f.items[2]!);await fill('Complete','Fictional stale batch must not overwrite a parallel task revision.');const changed=(await reviseWork({...f.items[1]!,version:2},workEdit({...f.items[1]!,version:2},{status:'Blocked'}))).json<WorkItem>();assert.equal(changed.version,3);await ui.click('Save selected task statuses');await eventually(async()=>(await ui.text()).includes('A selected task changed.'),'entire stale batch rejected');assert.equal((await f.rows()).find(i=>i.id===f.items[2]!.id).version,2);
  await ui.click('Discard selection and refresh tasks');await eventually(async()=>await b.evaluate<boolean>(`!document.querySelector('[aria-label="Task status batch"]')&&document.querySelector('#work-${f.items[1]!.id}')?.innerText.includes('Blocked')`),'conflict refreshed');await select(f.items[1]!);await select(f.items[2]!);await fill('Complete','Fictional investigator records completion after checking both current tasks.');await ui.click('Save selected task statuses');await eventually(async()=>(await ui.text()).includes('Recorded status changes for 2 tasks.'),'current selection committed');
  await b.evaluate(`document.querySelector('[aria-label="History for ${f.items[1]!.title}"]').click()`);await eventually(async()=>await b.evaluate<boolean>(`document.querySelector('#work-${f.items[1]!.id}')?.innerText.includes('Version 4')`),'individual history preserved');
  const filter=async(value:string)=>b.evaluate(`(()=>{const field=document.querySelector('[aria-label="Filter case tasks"]');Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(field,${JSON.stringify(value)});field.dispatchEvent(new Event('input',{bubbles:true}));})()`);
  await filter(f.items[0]!.title);assert.ok(await b.evaluate<boolean>(`!document.querySelector('#work-${f.items[1]!.id}')`));await select(f.items[0]!);await filter('');assert.ok(await b.evaluate<boolean>(`document.querySelector('[aria-label="Selected task versions"]').innerText.includes(${JSON.stringify(f.items[0]!.title)})`));await fill('Blocked','Fictional unsent coordination reason for the remaining task.');
  const artifact=fileURLToPath(new URL('../../../output/evals/task-batch-desktop.png',import.meta.url));await mkdir(resolve(artifact,'..'),{recursive:true});await b.evaluate(`document.querySelector('[aria-label="Task status batch"]').closest('.panel').scrollIntoView({block:'start'})`);const shot=await b.send<{data:string}>('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});await writeFile(artifact,Buffer.from(shot.data,'base64'));
  dropWorkspace=true;await ui.click('Refresh tasks');await eventually(async()=>await b.evaluate<boolean>(`!!document.querySelector('[role="alert"]')&&!document.querySelector('#work-${f.items[0]!.id}')&&!document.querySelector('[aria-label="Task status batch"]')`),'interrupted refresh hides stale task board');assert.ok(workspaceDrops>0);dropWorkspace=false;await ui.click('Refresh tasks');await eventually(async()=>await b.evaluate<boolean>(`!!document.querySelector('#work-${f.items[0]!.id}')`),'task board recovered');
  await b.send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});assert.ok(await b.evaluate<boolean>('document.documentElement.scrollWidth<=window.innerWidth+1'));
  await select(f.items[0]!);await fill('Blocked','Fictional private unsent task selection must clear when access is revoked.');await context.schemaAdminPool!.query('DELETE FROM case_memberships WHERE tenant_id=$1 AND case_id=$2 AND user_id=$3',[demoTenantId,f.kase.id,demoUserId]);await ui.click('Save selected task statuses');await eventually(async()=>await b.evaluate<boolean>(`!document.querySelector('#work-${f.items[0]!.id}')&&!document.querySelector('[aria-label="Task status batch"]')&&![...document.querySelectorAll('[aria-label="Active case"] option')].some(o=>o.value===${JSON.stringify(f.kase.id)})`)&&!(await ui.text()).includes('Fictional private unsent task selection'),'revoked task selection and reason cleared');assert.equal((await f.rows()).find(i=>i.id===f.items[0]!.id).version,2);
 },{response:(path,status)=>{if(dropBatch&&path===f.base&&status===200){batchDrops++;return 'drop';}if(dropWorkspace&&path==='/api/workspace'&&status===200){workspaceDrops++;return 'drop';}}});
});

async function fieldFixture(){
 await context.app!.close();context.app=await createAppInstance();context.demo=await issueTestSession(demoUserId);
 const kase=await createCase();assert.equal((await approveAuthority(kase.id)).statusCode,200);
 const deviceId=randomUUID(),device=await request('POST','/api/field/devices',context.demo!,{payload:{id:deviceId,label:'Fictional Field acceptance device'}});assert.equal(device.statusCode,200,device.body);
 const response=await request('GET',`/api/cases/${kase.id}/field-context/${deviceId}`,context.demo!);assert.equal(response.statusCode,200,response.body);const scope=response.json();
 const text='Fictional offline observation. No real data.',manifest={id:randomUUID(),deviceId,authorityId:scope.authority.id,authorityVersion:scope.authority.version,filename:'fictional-field-note.txt',sourceTime:'2026-10-01T09:00:00+01:00',capturedAt:'2026-10-02T10:00:00Z',clockUncertaintySeconds:null,method:'Fictional authorised written field note',expectedSha256:digest(text),byteLength:Buffer.byteLength(text),kind:'field_note',scopeConfirmed:true};
 const input={manifest,contentBase64:Buffer.from(text).toString('base64')},base=`/api/cases/${kase.id}/field-captures`;return {kase,deviceId,scope,text,input,base,send:(payload:object=input,session=context.demo!)=>request('POST',base,session,{payload})};
}
test('field captures preserve original bytes and distinct timestamps with immutable retry receipts',async()=>{
 const f=await fieldFixture(),first=await f.send();assert.equal(first.statusCode,200,first.body);const receipt=first.json();assert.equal(receipt.evidence.sourceTime,f.input.manifest.sourceTime);assert.equal(receipt.evidence.digest,digest(f.text));assert.equal(receipt.evidence.status,'Quarantined');assert.notEqual(receipt.capture.receivedAt,f.input.manifest.capturedAt);
 const rows=(await request('GET',f.base,context.demo!)).json().items;assert.equal(rows.length,1);assert.deepEqual(rows[0].manifest,f.input.manifest);assert.equal(rows[0].manifest.clockUncertaintySeconds,null);
 const original=await request('GET',`/api/cases/${f.kase.id}/evidence/${receipt.evidence.id}/original`,context.demo!);assert.equal(original.statusCode,200,original.body);assert.equal(original.body,f.text);
 assert.deepEqual((await f.send()).json(),receipt);assertError(await f.send({...f.input,manifest:{...f.input.manifest,method:'Different fictional acquisition'}}),409);
 await assert.rejects(context.schemaAdminPool!.query("UPDATE field_captures SET manifest='{}' WHERE case_id=$1",[f.kase.id]),/append|immutable/i);
 assert.equal((await context.pool!.query('SELECT count(*)::int n FROM evidence WHERE case_id=$1',[f.kase.id])).rows[0].n,1);
});
