async function transcriptFindingFixture(corrected=false){
 const f=await interviewFixture(),author=await createMember(demoTenantId,'investigator','Fictional transcript interpreter');await context.schemaAdminPool!.query('INSERT INTO case_memberships(tenant_id,case_id,user_id) VALUES($1,$2,$3)',[demoTenantId,f.kase.id,author]);const session=await issueTestSession(author);
 if(corrected){const r=await request('POST',f.editUrl,session,{payload:f.edit});assert.equal(r.statusCode,200,r.body);}
 const quote=corrected?f.edit.text:f.segments[0]!.text,input={id:randomUUID(),transcriptId:f.input.id,segmentId:f.segments[0]!.id,expectedVersion:corrected?1:0,text:'The supplied fictional transcript records uncertainty about the date.',startByte:0,endByte:Buffer.byteLength(quote),quote},base=`/api/cases/${f.kase.id}/transcript-claims`;
 const propose=(payload:object=input,actor=session)=>request('POST',base,actor,{payload});const proposed=await propose();assert.equal(proposed.statusCode,200,proposed.body);const claim=proposed.json(),decision={id:randomUUID(),digest:claim.digest,accepted:true,reason:'Fictional independent reading of the exact supplied transcript and retained correction.'},review=(payload:object=decision,actor=context.demo!)=>request('POST',base+'/'+claim.id+'/review',actor,{payload});
 return {...f,author,session,claim,input,base,decision,propose,review};
}
test('transcript finding proposals require independent version-bound review and preserve rejected/withdrawn history',async()=>{
 const f=await transcriptFindingFixture(true);assertError(await request('GET',`/api/cases/${f.kase.id}/report`,context.demo!),422);assertError(await f.review(f.decision,f.session),403);await context.schemaAdminPool!.query("UPDATE memberships SET role='reviewer' WHERE tenant_id=$1 AND user_id=$2",[demoTenantId,f.author]);assertError(await f.review(f.decision,f.session),403);
 assertError(await f.review({...f.decision,digest:'a'.repeat(64)}),409);const accepted=await f.review();assert.equal(accepted.statusCode,200,accepted.body);assert.equal(accepted.json().state,'reviewed');assert.ok(accepted.json().findingId);assert.deepEqual((await f.review()).json(),accepted.json());assertError(await f.review({...f.decision,accepted:false}),409);
 const report=await request('GET',`/api/cases/${f.kase.id}/report`,context.demo!);assert.equal(report.statusCode,200,report.body);assert.equal(report.json().findings.length,0);assert.equal(report.json().transcriptFindings[0].claim.transcript.corrections.length,1);
 assert.equal((await request('POST',f.editUrl,f.session,{payload:{...f.edit,id:randomUUID(),expectedVersion:1,text:'Fictional newer account requires a new assessment.'}})).statusCode,200);assert.equal((await request('GET',f.base,context.demo!)).json().items[0].state,'needs_review');assertError(await request('GET',`/api/cases/${f.kase.id}/report`,context.demo!),409);assert.deepEqual((await f.propose()).json(),f.claim);
 const withdrawal={id:randomUUID(),reason:'Fictional correction supersedes the earlier reviewed interpretation.'};const withdrawn=await request('POST',f.base+'/'+f.claim.id+'/withdraw',context.demo!,{payload:withdrawal});assert.equal(withdrawn.statusCode,200,withdrawn.body);assert.equal(withdrawn.json().state,'withdrawn');assert.equal(withdrawn.json().review.accepted,true);assert.deepEqual((await request('POST',f.base+'/'+f.claim.id+'/withdraw',context.demo!,{payload:withdrawal})).json(),withdrawn.json());
 await assert.rejects(context.schemaAdminPool!.query('DELETE FROM transcript_claims WHERE case_id=$1',[f.kase.id]),/append|immutable/i);await assert.rejects(context.schemaAdminPool!.query("UPDATE transcript_claim_reviews SET accepted=false WHERE case_id=$1",[f.kase.id]),/append|immutable/i);
});
test('transcript findings freeze exact lineage and independently verify report and versioned exhibits outside the repository',async()=>{
 const f=await transcriptFindingFixture(true);assert.equal((await f.review()).statusCode,200);const url=`/api/cases/${f.kase.id}/report-revisions`,freeze=await request('POST',url,context.demo!,{payload:{idempotencyKey:randomUUID()}});assert.equal(freeze.statusCode,200,freeze.body);const receipt=freeze.json(),report=await request('GET',url+'/'+receipt.id,context.demo!);assert.equal(report.statusCode,200,report.body);
 assert.equal((await request('POST',url+'/'+receipt.id+'/verify-sources',context.demo!,{payload:{sha256:receipt.sha256}})).statusCode,200);
 const root=await mkdtemp('/tmp/inveos-transcript-finding-offline-');try{
  for(const name of ['verify_report.py','report_package.py'])await cp(fileURLToPath(new URL('../../../tools/'+name,import.meta.url)),join(root,name));await writeFile(join(root,'report.json'),report.body);
  const run=(args:string[])=>promisify(execFile)('python3',args,{cwd:root,timeout:10000,env:{...process.env,PYTHONPATH:''}});
  const checked=JSON.parse((await run(['verify_report.py','report.json','--expected-sha256',receipt.sha256])).stdout);assert.equal(checked.findingsChecked,1);assert.equal(checked.transcriptFindingsChecked,1);
  const script="from pathlib import Path; import json; from report_package import build_package,verify_package; data=build_package(Path('report.json').read_bytes(),'2026-10-30T00:00:00Z'); Path('report.zip').write_bytes(data); print(json.dumps(verify_package(data)))";
  const packaged=JSON.parse((await run(['-c',script])).stdout);assert.equal(packaged.schemaVersion,'inveos.internal-exhibit-package.v2');
  const malformed=report.json();malformed.transcriptFindings[0].claim.transcript.raw.text='Fictional fabricated raw account';await writeFile(join(root,'invalid.json'),JSON.stringify(malformed));await assert.rejects(run(['verify_report.py','invalid.json']));
 }finally{await rm(root,{recursive:true,force:true});}
 assert.equal((await request('POST',f.editUrl,f.session,{payload:{...f.edit,id:randomUUID(),expectedVersion:1,text:'Fictional later correction retained separately.'}})).statusCode,200);assert.equal((await request('GET',url+'/'+receipt.id,context.demo!)).body,report.body);assertError(await request('POST',url+'/'+receipt.id+'/verify-sources',context.demo!,{payload:{sha256:receipt.sha256}}),409);
});
