  const frozen=await request('POST',f.revisionsUrl,context.demo!,{payload:{idempotencyKey:randomUUID()}});assert.equal(frozen.statusCode,200,frozen.body);const revision=frozen.json(),base=`${f.revisionsUrl}/${revision.id}/editable-renditions`,input={idempotencyKey:randomUUID(),redactedFindingIds:[f.decision.id],reason:'Fictional scoped withholding of the complete finding.'};
