async function collectionFixture(limit=10){
 await context.app!.close();context.app=await createAppInstance();context.demo=await issueTestSession(demoUserId);
 const kase=await createCase();assert.equal((await approveAuthority(kase.id)).statusCode,200);
 const reviewerId=await createMember(demoTenantId,'reviewer','Fictional OSINT policy reviewer'),investigatorId=await createMember(demoTenantId,'investigator','Fictional OSINT collector');
 for(const id of [reviewerId,investigatorId])await context.schemaAdminPool!.query('INSERT INTO case_memberships(tenant_id,case_id,user_id) VALUES($1,$2,$3)',[demoTenantId,kase.id,id]);
 const reviewer=await issueTestSession(reviewerId),investigator=await issueTestSession(investigatorId),policy='/api/connector-policies/companies_house_profile_v1';
 const history=parseBody<{items:{version:number}[]}>(await request('GET',policy,context.demo!));const version=(history.items[0]?.version??0)+1;
 const proposal={id:randomUUID(),adapterId:'companies_house_profile_v1',expectedVersion:version-1,profileDigest:connectorProfileDigest,purpose:'Fictional company lookup integration fixture',lawfulBasis:'Fictional data only; no live investigative collection',termsReference:'https://example.invalid/fictional-source-terms',termsSha256:digest('Fictional source terms, not a provider approval'),minimisation:'One fictional company profile only; no linked lookup',retentionDays:30,requestsPerWindow:limit,validUntil:new Date(Date.now()+3600000).toISOString(),reason:'Fictional source-policy integration exercise'};
 assert.equal((await request('POST',policy,context.demo!,{payload:proposal})).statusCode,200);
 const decision={id:randomUUID(),accepted:true,reason:'Fictional test source policy independently reviewed',legalApprovalReference:'Fictional approval fixture; no actual provider permission'};
 assertError(await request('POST',policy+`/${version}/review`,context.demo!,{payload:decision}),403);
 assert.equal((await request('POST',policy+`/${version}/review`,reviewer,{payload:decision})).statusCode,200);
 const base=`/api/cases/${kase.id}/collection`,authorisation={id:randomUUID(),policyVersion:version,authorityVersion:1,companyNumber:'FIC00001',purpose:'Verify the fictional company profile response',minimisation:'Retain one fictional profile without following linked records',retentionDays:7,validUntil:new Date(Date.now()+1800000).toISOString()};
 assert.equal((await request('POST',base+'/authorisations',context.demo!,{payload:authorisation})).statusCode,200);
 const queue=async()=>{const id=randomUUID();const response=await request('POST',base+'/jobs',investigator,{payload:{id,authorisationId:authorisation.id}});assert.equal(response.statusCode,200,response.body);return id;};
 const scope={pool:context.pool!,storage:context.storageRoot!,tenantId:demoTenantId,caseId:kase.id,credentialScope:digest(randomUUID())};
 return {kase,base,policy,version,authorisation,proposal,reviewer,reviewerId,investigator,investigatorId,queue,scope};
}
function fictionalCompanyResponse(overrides:Partial<CollectionResponse>={}):CollectionResponse{return {provenance:'fictional_fixture',status:200,body:Buffer.from(JSON.stringify({company_number:'FIC00001',company_name:'Northstar Paperworks (fictional)',company_status:'active',type:'ltd',date_of_creation:'2020-01-01',links:{officers:'/fictional-not-followed'},registered_office_address:{address_line_1:'Fictional fixture address only'}})),date:new Date().toUTCString(),etag:'fictional-etag',contentType:'application/json',retryAfter:null,...overrides};}
async function withFictionalHttp<T>(respond:(req:import('node:http').IncomingMessage,res:import('node:http').ServerResponse)=>void,run:(transport:CollectionTransport)=>Promise<T>){
 const server=createServer(respond);await new Promise<void>(resolve=>server.listen(0,'127.0.0.1',resolve));const address=server.address() as {port:number};
 const transport:CollectionTransport=async(number,signal)=>{const r=await fetch(`http://127.0.0.1:${address.port}/fictional-company/${number}`,{signal,redirect:'error'});return {provenance:'fictional_fixture',status:r.status,body:Buffer.from(await r.arrayBuffer()),date:r.headers.get('date'),etag:r.headers.get('etag'),contentType:r.headers.get('content-type')??'',retryAfter:r.headers.get('retry-after')};};
 try{return await run(transport);}finally{server.closeAllConnections();await new Promise<void>(resolve=>server.close(()=>resolve()));}
}

test('OSINT collection records raw HTTP bytes and unreviewed source assertions under scoped authority',async()=>{
 const f=await collectionFixture(),jobId=await f.queue(),raw=fictionalCompanyResponse().body;let calls=0;
 await withFictionalHttp((req,res)=>{calls++;assert.equal(req.url,'/fictional-company/FIC00001');res.writeHead(200,{'content-type':'application/json',etag:'fictional-etag'});res.end(raw);},async transport=>assert.equal(await runCollectionJob({...f.scope,jobId,transport}),'succeeded'));
 const exported=await request('GET',f.base+'/jobs/'+jobId+'/export',f.investigator);assert.equal(exported.statusCode,200,exported.body);const root=await mkdtemp('/tmp/inveos-collection-offline-');try{await cp(fileURLToPath(new URL('../../../tools/verify_collection_context.py',import.meta.url)),join(root,'verify.py'));await writeFile(join(root,'context.json'),exported.body);const run=(args:string[])=>promisify(execFile)('python3',args,{cwd:root,env:{...process.env,PYTHONPATH:''},timeout:10000});const checked=JSON.parse((await run(['verify.py','context.json','--expected-sha256',exported.json().sha256])).stdout);assert.equal(checked.status,'consistency_checks_passed');assert.equal(checked.clientReleaseApproved,false);const tamper="import json;from pathlib import Path;from verify import verify,digest;p=json.loads(Path('context.json').read_text());p['payload']['receipt']['fields'][0]['value']='FIC99999';p['payload']['receiptSha256']=digest(p['payload']['receipt']);p['sha256']=digest(p['payload']);\ntry:verify(json.dumps(p).encode())\nexcept ValueError:print('rejected')\nelse:raise AssertionError('Rehashed field substitution accepted')";assert.equal((await run(['-c',tamper])).stdout.trim(),'rejected');assert.equal((await run(['-c',"import copy,json\nfrom pathlib import Path\nfrom verify import verify,digest\noriginal=json.loads(Path('context.json').read_text())\ncases=[('receipt','profileDigest','0'*64),('receipt','captureMode','live_approved'),('receipt','sourceTimeBasis','record_creation'),('receipt','tenantId','other'),('receipt','caseId','other'),('receipt','httpStatus',True),('receipt','authorityVersion',True),('receipt','companyNumber','FIC99999'),('receipt','interpretation','reviewed_finding'),('policyReview','accepted',1),('policyReview','reviewer_id',original['payload']['sourcePolicy']['proposed_by']),('policyReview','version',999),('authorisation','company_number','FIC99999'),('authorisation','valid_until','2020-01-01T00:00:00Z'),('authorisation','retention_days',3650),('caseAuthority','id','other'),('sourcePolicy','requests_per_window',601),('sourcePolicy','requests_per_window',True),('sourcePolicy','terms_sha256','invalid')]\nfor group,key,value in cases:\n p=copy.deepcopy(original);p['payload'][group][key]=value;p['payload']['receiptSha256']=digest(p['payload']['receipt']);p['sha256']=digest(p['payload'])\n try:verify(json.dumps(p).encode())\n except (ValueError,TypeError):pass\n else:raise AssertionError('Rehashed semantic mutation accepted: '+group+'.'+key)\nprint(len(cases))\n"])).stdout.trim(),'19');}finally{await rm(root,{recursive:true,force:true});}
 assert.equal(calls,1);assert.equal(await runCollectionJob({...f.scope,jobId,transport:async()=>{throw Error('Never repeat a successful request');}}),'not_queued');
 const detail=parseBody<{job:{evidenceId:string;sourceId:string};receipt:{fields:{pointer:string;value:string}[];originalSha256:string;sourceTimeBasis:string};events:{status:string}[]}>(await request('GET',f.base+'/jobs/'+jobId,f.investigator));
 assert.equal(detail.receipt.originalSha256,digest(raw.toString()));assert.equal(detail.receipt.sourceTimeBasis,'http_response_date_not_record_creation');assert.ok(detail.receipt.fields.some(x=>x.pointer==='/company_name'));assert.ok(!detail.receipt.fields.some(x=>x.pointer.includes('address')));assert.deepEqual(detail.events.map(x=>x.status),['queued','running','succeeded']);
 const original=await request('GET',`/api/cases/${f.kase.id}/evidence/${detail.job.evidenceId}/original`,f.investigator);assert.equal(original.statusCode,200,original.body);assert.equal(original.body,raw.toString());
 const use=await request('GET',`/api/cases/${f.kase.id}/manual-sources/${detail.job.sourceId}/use-decisions`,context.demo!);assert.equal(use.statusCode,200,use.body);assert.equal(parseBody<{analysisAllowed:boolean}>(use).analysisAllowed,false);
 const unrelated=await createCase();assertError(await request('GET',`/api/cases/${unrelated.id}/collection/jobs/${jobId}`,context.demo!),404);
 await assert.rejects(context.pool!.query('UPDATE collection_captures SET receipt=$4::jsonb WHERE tenant_id=$1 AND case_id=$2 AND job_id=$3',[demoTenantId,f.kase.id,jobId,'{}']));
 await assert.rejects(context.pool!.query("UPDATE collection_jobs SET status='queued',finished_at=NULL WHERE tenant_id=$1 AND case_id=$2 AND id=$3",[demoTenantId,f.kase.id,jobId]));
});

