 const result={context:{...scope,evidenceId:evidence.id,sourceDigest:evidence.digest,authorityVersion:job.authorityVersion},profileDigest:speechProfileDigest,successful:true,raw:Buffer.from(JSON.stringify({format:'inveos.whisper_research.v1',sampleRate:16000,samples:(bytes.length-44)/2,segments:[{startMs:0,endMs:invalidRange?10000:3000,text:' Fictional supplier account.'}]}))},base=`/api/cases/${kase.id}/speech-transcripts/${job.id}`,claims=`/api/cases/${kase.id}/speech-claims`;
